mapper.select:
SELECT a.article_id, a.title, a.summary, a.category_id, a.cover_image,
       a.view_count, a.like_count, a.collect_count, a.comment_count,
       a.author_id, a.author_name, a.related_resource_id, a.related_resource_title,
       a.status, a.is_top, a.is_recommend, a.is_original,
       a.create_time, a.update_time, a.publish_time,
       c.category_name
FROM my_article a
LEFT JOIN article_category c ON a.category_id = c.category_id


        AND a.status = #{params.status}


        AND (a.title LIKE CONCAT('%', #{params.keyword}, '%')
        OR a.summary LIKE CONCAT('%', #{params.keyword}, '%'))


        AND a.category_id = #{params.categoryId}


        AND a.author_id = #{params.authorId}


        AND a.is_top = #{params.isTop}


        AND a.is_recommend = #{params.isRecommend}


ORDER BY a.is_top DESC, a.create_time DESC

SELECT * FROM my_article
WHERE author_id = #{authorId}

    AND status = #{params.status}

ORDER BY create_time DESC
